import bpy,json,hashlib,bmesh
R=Path('/Users/kazuki.tanaka/dev0/exfract-bonsai-02/improvement/2026-10-04/runs/native-grip-0017');sha=lambda a:hashlib.sha256(json.dumps(a).encode()).hexdigest();rows=[]
for version,suffix in [('grip-v01',''),('grip-v02','-v02')]:
 file=R/'models'/f'{version}-editable.blend';bpy.ops.wm.open_mainfile(filepath=str(file));o=next(x for x in bpy.data.objects if x.type=='MESH');me=o.data;rec=json.loads((R/'sculpt'/f'sculpt-record{suffix}.json').read_text());checks={'positions':sha([list(v.co)for v in me.vertices])==rec['positions_sha256'],'faces':sha([list(f.vertices)for f in me.polygons])==rec['faces_sha256'],'normals':sha([list(v.normal)for v in me.vertices])==rec['normals_sha256'],'colors':sha([list(c.color)for c in me.color_attributes.active_color.data])==rec['color_sha256'],'uv':{u.name:sha([list(v.uv)for v in u.data])==rec['uv_sha256'][u.name]for u in me.uv_layers},'authoring_version':o['authoring_version']==version};assert all(v if isinstance(v,bool) else all(v.values())for v in checks.values());bm=bmesh.new();bm.from_mesh(me);boundary=sum(e.is_boundary for e in bm.edges);nonmanifold=sum(not e.is_manifold for e in bm.edges);volume=bm.calc_volume(signed=True);bm.free();assert boundary==nonmanifold==0 and abs(volume-rec['geometry']['volume'])<1e-12;rows.append({'version':version,'reopened':True,'native_sha256':hashlib.sha256(file.read_bytes()).hexdigest(),'checks':checks,'boundary_edges':boundary,'nonmanifold_edges':nonmanifold,'volume':volume,'modifiers':len(o.modifiers),'geometry_only_not_aesthetic':True})
(R/'qa/native-roundtrip.json').write_text(json.dumps(rows,indent=2)+'\n');print(json.dumps(rows))
